import pandas as pd

import config
from src import common

LINES = []


def say(text=""):
    print(text)
    LINES.append(str(text))


def pct(part, whole):
    return "n/a" if whole == 0 else f"{100 * part / whole:.1f}%"


def check_facades():
    say("=" * 70)
    say("FACADE FILINGS")
    say("=" * 70)
    df = common.read_raw("facades")
    say(f"Rows: {len(df):,}   Columns: {df.shape[1]}")
    say("Column names in the file:")
    say("  " + ", ".join(df.columns))

    missing = common.missing_facade_columns(df)
    if missing:
        say("\nConfigured names NOT found in the file (fix FACADE_COLS in config.py):")
        for key, name in missing.items():
            need = "REQUIRED" if key in config.FACADE_REQUIRED else "optional"
            say(f"  {key:15s} -> '{name}'   [{need}]")
    else:
        say("\nEvery configured column name was found.")

    say("\nValues in every column whose name mentions status, type or cycle")
    say("(use these to confirm which column holds this filing's rating):")
    for col in df.columns:
        if any(word in col for word in ("status", "type", "cycle")):
            counts = df[col].fillna("<blank>").value_counts().head(12)
            say(f"\n  [{col}]")
            for value, n in counts.items():
                say(f"    {str(value)[:50]:50s} {n:>8,}")

    blocked = [k for k in config.FACADE_REQUIRED if k in missing]
    if blocked:
        say(f"\nSTOP: required columns missing ({', '.join(blocked)}). "
            "Fix config.py and run this again.")
        return None

    c = config.FACADE_COLS
    initial = df[common.is_initial_filing(df[c["filing_type"]])].copy()
    initial["rating"] = common.normalize_status(initial[c["label_status"]])
    rated = initial[initial["rating"].isin(common.RATINGS)].copy()

    say("\n--- NUMBER 1: ratings on initial filings ---")
    say(f"Initial filings: {len(initial):,} of {len(df):,} rows")
    say(f"Initial filings with a Safe / SWARMP / Unsafe rating: {len(rated):,}")
    for rating in common.RATINGS:
        n = (rated["rating"] == rating).sum()
        say(f"  {rating:8s} {n:>8,}   {pct(n, len(rated))}")
    say(f"Buildings (distinct BINs) with a rated initial filing: "
        f"{common.clean_id(rated[c['bin']]).nunique():,}")

    rated["filing_dt"] = pd.to_datetime(rated[c["filing_date"]], errors="coerce")
    ok = rated["filing_dt"].notna().sum()
    say("\n--- NUMBER 3: usable filing dates ---")
    say(f"Rated initial filings with a readable date: {ok:,} of {len(rated):,} "
        f"({pct(ok, len(rated))})")
    if ok:
        say(f"Date range: {rated['filing_dt'].min().date()} to {rated['filing_dt'].max().date()}")

    rated["bbl"] = common.make_bbl(rated[c["borough"]], rated[c["block"]], rated[c["lot"]])
    rated["bin_clean"] = common.clean_id(rated[c["bin"]])
    return rated


def check_pluto(rated):
    say("\n" + "=" * 70)
    say("PLUTO")
    say("=" * 70)
    pluto = common.read_raw("pluto")
    say(f"Rows: {len(pluto):,}   Columns: {', '.join(pluto.columns)}")
    if "bbl" not in pluto.columns:
        say("STOP: PLUTO has no 'bbl' column. Check DATASETS['pluto'] in config.py.")
        return
    keys = set(common.clean_pluto_bbl(pluto["bbl"]).dropna())
    built = rated["bbl"].notna().sum()
    matched_rows = rated["bbl"].isin(keys).sum()
    buildings = rated.drop_duplicates("bin_clean")
    matched_bldg = buildings["bbl"].isin(keys).sum()
    say("\n--- NUMBER 2: PLUTO match rate (target: 90% or more) ---")
    say(f"Filings where a 10-digit BBL could be built: {built:,} of {len(rated):,} "
        f"({pct(built, len(rated))})")
    say(f"Filings matched to a PLUTO lot:   {matched_rows:,} of {len(rated):,} "
        f"({pct(matched_rows, len(rated))})")
    say(f"Buildings matched to a PLUTO lot: {matched_bldg:,} of {len(buildings):,} "
        f"({pct(matched_bldg, len(buildings))})")


def check_ecb(rated):
    say("\n" + "=" * 70)
    say("ECB VIOLATIONS")
    say("=" * 70)
    ecb = common.read_raw("ecb")
    say(f"Rows: {len(ecb):,}   Columns: {', '.join(ecb.columns)}")
    need = [col for col in ("bin", "issue_date", "severity", "violation_type")
            if col not in ecb.columns]
    if need:
        say(f"STOP: missing columns {need}. Check DATASETS['ecb'] in config.py.")
        return
    ecb["bin_clean"] = common.clean_id(ecb["bin"])
    ours = ecb[ecb["bin_clean"].isin(set(rated["bin_clean"].dropna()))]
    dated = common.parse_ecb_date(ours["issue_date"]).notna().sum()
    bldgs = rated["bin_clean"].nunique()
    say(f"Violations on our buildings: {len(ours):,}")
    say(f"Our buildings with at least one violation: {ours['bin_clean'].nunique():,} "
        f"of {bldgs:,} ({pct(ours['bin_clean'].nunique(), bldgs)})")
    say(f"Violations with a readable issue date: {dated:,} of {len(ours):,} "
        f"({pct(dated, len(ours))})")
    for col in ("severity", "violation_type"):
        say(f"\n  [{col}]")
        for value, n in ours[col].fillna("<blank>").value_counts().head(8).items():
            say(f"    {str(value)[:50]:50s} {n:>8,}")


def main():
    rated = check_facades()
    if rated is not None:
        for step in (check_pluto, check_ecb):
            try:
                step(rated)
            except FileNotFoundError as err:
                say(f"\nSkipped: {err}")
    config.RESULTS_DIR.mkdir(parents=True, exist_ok=True)
    report = config.RESULTS_DIR / "data_check_report.txt"
    report.write_text("\n".join(LINES), encoding="utf-8")
    print(f"\nReport saved to {report}")


if __name__ == "__main__":
    main()
